// Strip hidden/invisible text before it reaches the AI (prompt-injection hygiene)
// and skip messages this workflow already handled (no duplicate drafts on re-runs).
const sd = $getWorkflowStaticData('global');
const processed = sd.processed || [];
const out = [];
for (const item of $input.all()) {
  const m = item.json;
  if (m.id && processed.includes(m.id)) continue;
  let body;
  if (m.html) {
    body = String(m.html)
      .replace(/<!--[\s\S]*?-->/g, ' ')
      .replace(/<(script|style|head|title)\b[\s\S]*?<\/\1>/gi, ' ')
      .replace(/<([a-z0-9]+)\b[^>]*style\s*=\s*["'][^"']*(display\s*:\s*none|visibility\s*:\s*hidden|font-size\s*:\s*0|opacity\s*:\s*0|max-height\s*:\s*0)[^"']*["'][^>]*>[\s\S]*?<\/\1>/gi, ' ')
      .replace(/<br\s*\/?>/gi, '\n')
      .replace(/<\/(p|div|li|tr|h[1-6])>/gi, '\n')
      .replace(/<[^>]+>/g, ' ')
      .replace(/&nbsp;/g, ' ').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
      .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&amp;/g, '&');
  } else {
    body = String(m.text || m.snippet || '');
  }
  body = body
    .replace(/[​-‏‪-‮⁠-⁤﻿­]/g, '')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n\s*\n\s*\n+/g, '\n\n')
    .trim()
    .slice(0, 6000);
  out.push({
    json: {
      message_id: m.id,
      thread_id: m.threadId,
      subject: m.subject || '',
      from_address: (m.from && m.from.value && m.from.value[0] && m.from.value[0].address) || '',
      body,
    },
  });
}
return out;

