// Validate the AI output. Anything unexpected goes to "needs_review" instead of silently disappearing.
const CATEGORIES = ['sales_lead', 'billing_invoice', 'support'];
const URGENCIES = ['high', 'normal'];
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const email = $('1B. Clean & Dedupe Email').itemMatching(i).json;
  const res = items[i].json;
  let r = null;
  let reason = '';
  try {
    const content = res.choices && res.choices[0] && res.choices[0].message && res.choices[0].message.content;
    if (!content) throw new Error((res.error && (res.error.message || res.error)) || 'empty AI response');
    r = JSON.parse(content);
  } catch (e) {
    reason = 'AI output unusable: ' + e.message;
  }
  if (r && !reason) {
    if (!CATEGORIES.includes(r.category)) reason = 'unexpected category: ' + r.category;
    else if (!URGENCIES.includes(r.urgency)) reason = 'unexpected urgency: ' + r.urgency;
    else if (!r.draft_reply || !String(r.draft_reply).trim()) reason = 'empty draft_reply';
  }
  const ok = !reason;
  let route = 'needs_review';
  if (ok) route = (r.category === 'sales_lead' && r.urgency === 'high') ? 'hot_lead' : (r.urgency === 'high' ? 'urgent' : 'normal');
  out.push({
    json: {
      ...email,
      route,
      review_reason: reason,
      category: ok ? r.category : null,
      urgency: ok ? r.urgency : null,
      summary: ok ? String(r.summary || '') : '',
      draft_reply: ok ? String(r.draft_reply) : '',
      gmail_link: 'https://mail.google.com/mail/u/0/#all/' + email.thread_id,
    },
    pairedItem: { item: i },
  });
}
return out;

