// Remember handled message IDs so a re-run never stacks a second draft in the same thread.
// Note: workflow static data is only saved for production (active) executions, not manual test runs.
const sd = $getWorkflowStaticData('global');
const processed = sd.processed || [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const id = $('2B. Parse & Validate AI Output').itemMatching(i).json.message_id;
  if (id && !processed.includes(id)) processed.push(id);
}
sd.processed = processed.slice(-1000);
return items;
